                mask = frozenset(cells)
                if mask == frozenset({(0,0),(0,1),(1,0),(1,2),(2,1)}):  # right
                    commands.append((color, 2, 1, 'h'))
                elif mask == frozenset({(0,0),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)}):  # left
                    commands.append((color, -1, 1, 'h'))
