            # The down segment's column/color are retained explicitly in state.
            if r + 1 < h and 0 <= c + 1 < 7:
                out[r + 1][c + 1] = prev[-2][0]
                r += 1
        nr, nc = r + dy, c + dx
        if orient == 'h':
            if nr < h:
                for x in range(min(c, nc), max(c, nc) + 1):
